var t=`0783-piri-piri-prawns`;var n=`world-0783`;var r=`MZ`;var s=`eastern-africa`;var a=4;var o=42;var g={en:`Piri-Piri Prawns`,ua:`Креветки пірі-пірі`};var h={en:`Piri-Piri Prawns is a Mozambique classic prepared with shrimp, garlic, lemon juice, scotch bonnet pepper. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Креветки пірі-пірі, страва кухні країни Мозамбік зі складниками: креветка, часник, лимонний сік, перець скотч-боннет. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 30 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 30 хвилин.`,t:[`marinating`],m:30,i:[[`shrimp`,770,`g`],[`garlic`,6,`clove`],[`lemon-juice`,50,`ml`],[`scotch-bonnet-pepper`,1,`pcs`],[`hot-paprika`,6,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`unsalted-butter`,60,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,22,`g`]]}];var p={slug:t,id:n,country:`MZ`,region:s,servings:4,minutes:42,title:g,text:h,steps:m};export{r as country,p as default,n as id,o as minutes,s as region,a as servings,t as slug,m as steps,h as text,g as title};